#include <list.h>
#include <assert.h>

typedef float rational_t;
typedef rational_t time_value_t;

class ai_goal;

class ai_action
{
public:
  enum
  {
    IN_SERVICE      = 0x00000001
  };

  ai_action(ai_goal *own);
  virtual ~ai_action() { }

  // returns  TRUE = POP_ME
  //         bsptr = PUSH_THIS
  virtual bool frame_advance( time_value_t delta_t ) = 0;

  virtual void going_out_of_service();
  virtual void going_into_service();

  inline bool is_flagged(int flag) const          { return((flags & flag) != 0); }
  inline void set_flag(int flag, bool on = true)  { if(on) flags |= flag; else flags &= ~flag; }

  inline bool is_in_service()                     { return(is_flagged(IN_SERVICE)); }

  inline ai_goal *get_ai_goal() const             { return(owner); }
  inline unsigned int get_id() const              { return(id); }

protected:
  ai_goal *owner;
  int flags;
  unsigned int id;

private:
  static unsigned int action_id_counter;
};

class ai_goal
{
protected:
  rational_t priority;
  rational_t priority_modifier;
  bool in_service;
  list<ai_action *> actions;

  virtual rational_t frame_advance(time_value_t t);
};

rational_t ai_goal::frame_advance(time_value_t t)
{
  // NB: TWO RETURN VALUES ARE HAPPENING HERE
  list<ai_action *>::iterator i = actions.begin();
  while(i != actions.end())
  {
    ai_action *action = (*i);
    assert(action->is_in_service());

    if( action->frame_advance( t ) )
    {
      action->going_out_of_service();
      delete action;

      i = actions.erase(i);
    }
    else
      ++i;
  }

  return(priority);
}
